package main

import (
	"strconv"
	"strings"
)

func safeName(s string) bool {
	if s == "" { return false }
	for _, c := range []byte(s) {
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-' { continue }
		return false
	}
	return true
}

func positive(s string) (int, bool) {
	if s == "" { return 0, false }
	for _, c := range []byte(s) { if c < '0' || c > '9' { return 0, false } }
	n, err := strconv.ParseUint(s, 10, 63)
	if err != nil || n == 0 || uint64(int(n)) != n { return 0, false }
	return int(n), true
}

func unsigned(s string) (int, bool) {
	if s == "" { return 0, false }
	for _, c := range []byte(s) { if c < '0' || c > '9' { return 0, false } }
	n, err := strconv.ParseUint(s, 10, 63)
	if err != nil || uint64(int(n)) != n { return 0, false }
	return int(n), true
}

func parseRoll(sheet string) ([]Car, int) {
	var cars []Car
	for _, raw := range strings.Split(sheet, "\n") {
		line := strings.TrimSpace(raw)
		if line == "" || strings.HasPrefix(line, "#") { continue }
		w := strings.Fields(line)
		if len(w) != 12 || w[0] != "PLATE" || w[2] != "LEN" || w[4] != "HT" || w[6] != "MASS" || w[8] != "HAZ" || w[10] != "BOARD" || !safeName(w[1]) { return nil, -2 }
		length, a := positive(w[3]); ht, b := positive(w[5]); mass, c := positive(w[7]); haz, d := unsigned(w[9]); board, e := positive(w[11])
		if !a || !b || !c || !d || !e || haz > 1 { return nil, -2 }
		cars = append(cars, Car{Plate:w[1], Len:length, Ht:ht, Mass:mass, Haz:haz, Board:board, Index:len(cars)})
	}
	return cars, 0
}
EOF
