package main

type occ struct { used, mass, lastHaz int; has bool }
type offer struct { lane Lane; gap, station int; ok bool }

func pickLane(car Car, fill map[string]*occ, deckKg map[string]int) offer {
	for _, lane := range allLanes() {
		if car.Ht > lane.Lid { continue }
		slot := fill[lane.Name]
		gap, used := 0, 0
		if slot != nil && slot.has { gap, used = neighbourGap(slot.lastHaz, car.Haz), slot.used }
		if used+gap+car.Len+rampApron(car.Haz) > lane.Span { continue }
		if !massFits(lane, slot, car, deckKg[lane.Deck]) || !trimFits(lane, fill, car.Mass) { continue }
		return offer{lane:lane, gap:gap, station:stationOf(lane.Span-used, car, gap), ok:true}
	}
	return offer{}
}
