package main

import (
	"encoding/json"
	"strconv"
	"strings"
)

type result struct { ok bool; deck, lane string; station int }
type chalkRow struct {
	I int `json:"i"`
	Verb string `json:"verb"`
	Plate string `json:"plate"`
	Deck string `json:"deck,omitempty"`
	Lane string `json:"lane,omitempty"`
	Station string `json:"station,omitempty"`
	OK string `json:"ok"`
}

func fold(sheet string) (int, string) {
	cars, rc := parseRoll(sheet); if rc != 0 { return rc, "" }
	if len(cars) == 0 { return 0, "" }
	fill := map[string]*occ{}; deckKg := map[string]int{}; results := make([]result, len(cars))
	for _, car := range arrange(cars) {
		x := pickLane(car, fill, deckKg)
		if !x.ok { continue }
		slot := fill[x.lane.Name]; if slot == nil { slot=&occ{}; fill[x.lane.Name]=slot }
		slot.used += x.gap + car.Len + rampApron(car.Haz); slot.mass += car.Mass; slot.lastHaz=car.Haz; slot.has=true
		deckKg[x.lane.Deck] += car.Mass
		results[car.Index] = result{true, x.lane.Deck, x.lane.Name, x.station}
	}
	var out strings.Builder
	for i, car := range cars {
		r := results[i]; row := chalkRow{I:i+1, Verb:"stow", Plate:car.Plate, OK:"no"}
		if r.ok { row.Deck=r.deck; row.Lane=r.lane; row.Station=strconv.Itoa(r.station); row.OK="yes" }
		b,_ := json.Marshal(row); out.Write(b); out.WriteByte('\n')
	}
	return 0, out.String()
}
EOF

