package main

// neighbourGap returns extra space needed in addition to any ramp apron
// already reserved by the previous plate.
func neighbourGap(prevHaz, haz int) int {
	required := 0
	if prevHaz == 1 || haz == 1 {
		required = 100
	}
	if prevHaz == 1 && haz == 1 {
		required = 200
	}
	alreadyReserved := rampApron(prevHaz)
	if required > alreadyReserved {
		return required - alreadyReserved
	}
	return 0
}
EOF
